(419485, 37708, 327, '<td valign="top">Stroke, stroke. Pretty shot, good colors.</td>', 'Stroke, stroke. Pretty shot, good colors.', '2003-09-15 11:24:31.000000', NULL, 1),
(419486, 37842, 327, '<td valign="top">Wonderful shot....love the colors, light and action!!!!! Congrats.</td>', 'Wonderful shot....love the colors, light and action!!!!! Congrats.', '2003-09-15 11:26:10.000000', NULL, 1),
(419488, 37807, 327, '<td valign="top">Fantastic! Wonderful light, color, focus and ACTION!!!!!!!!!!!!!!! Great.</td>', 'Fantastic! Wonderful light, color, focus and ACTION!!!!!!!!!!!!!!! Great.', '2003-09-15 11:26:54.000000', NULL, 1),
(419489, 37007, 656, '<td valign="top">Problem is, it is tough to tell from the shot if your title is true or not.  He could just be lifting the ball up and tossing it - the shot doesn''t really let me know.  Ignoring that for now...<br/> <br/>Focus is really sharp,  and framing is excellent.  The soft background works to show him catching the ball and the facial expressions are strong (7)</td>', 'Problem is, it is tough to tell from the shot if your title is true or not.  He could just be lifting the ball up and tossing it - the shot doesn''t really let me know.  Ignoring that for now... Focus is really sharp,  and framing is excellent.  The soft background works to show him catching the ball and the facial expressions are strong (7)', '2003-09-15 11:27:13.000000', NULL, 1),
(419491, 37009, 327, '<td valign="top">Good capture, good work.</td>', 'Good capture, good work.', '2003-09-15 11:27:39.000000', NULL, 1),
