(419975, 37715, 8970, '<td valign="top">I wish either that i could see the upper part of the net, or that that dark grass on the bottom was cropped off</td>', 'I wish either that i could see the upper part of the net, or that that dark grass on the bottom was cropped off', '2003-09-15 18:42:45.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(419979, 37596, 8970, '<td valign="top">The dog appears to be a bit out of focus for a stop motion shot.  Probably would have looked better if the focus didn''t occur on the grass background.  But I love the dog with the frisbee.</td>', 'The dog appears to be a bit out of focus for a stop motion shot.  Probably would have looked better if the focus didn''t occur on the grass background.  But I love the dog with the frisbee.', '2003-09-15 18:45:03.000000', NULL, 1),
(419983, 37294, 8970, '<td valign="top">Wish I could have seen a ball in this picture</td>', 'Wish I could have seen a ball in this picture', '2003-09-15 18:46:38.000000', NULL, 1),
(419989, 37238, 8970, '<td valign="top">The glare from the sun is a little too strong.  The sky appears to be a sparkling blue and I love how the tennis ball is balanced.</td>', 'The glare from the sun is a little too strong.  The sky appears to be a sparkling blue and I love how the tennis ball is balanced.', '2003-09-15 18:48:31.000000', NULL, 1),
(419990, 37563, 10883, '<td valign="top">Great timing! Good expressions on the players faces! - 9</td>', 'Great timing! Good expressions on the players faces! - 9', '2003-09-15 18:49:31.000000', NULL, 1),
(419992, 37769, 8970, '<td valign="top">Wish a faster shutter speed was used for this image.</td>', 'Wish a faster shutter speed was used for this image.', '2003-09-15 18:50:09.000000', NULL, 1),
(419993, 37835, 10883, '<td valign="top">Good pic, good expression on their faces! - 9</td>', 'Good pic, good expression on their faces! - 9', '2003-09-15 18:50:12.000000', NULL, 1),
(419994, 37801, 10883, '<td valign="top">Great picture! Nice contrasts with the clear blue sky, white smoke and the yellow airplane! - 10</td>', 'Great picture! Nice contrasts with the clear blue sky, white smoke and the yellow airplane! - 10', '2003-09-15 18:50:43.000000', NULL, 1),
(419996, 37495, 8970, '<td valign="top">Those light glares complete destroyed this image, a polarizer might have helped removes those glares.</td>', 'Those light glares complete destroyed this image, a polarizer might have helped removes those glares.', '2003-09-15 18:52:40.000000', NULL, 1),
(419999, 37760, 8970, '<td valign="top">There is too much black space in this image.  I have no clue what these people are doing, because I feel like they are invisible people.</td>', 'There is too much black space in this image.  I have no clue what these people are doing, because I feel like they are invisible people.', '2003-09-15 18:54:12.000000', NULL, 1),
(420003, 37829, 8970, '<td valign="top">This image is a great find.  The vantage point is great.  However I never thought of chess as a sport.  It has always been a game in my mind.</td>', 'This image is a great find.  The vantage point is great.  However I never thought of chess as a sport.  It has always been a game in my mind.', '2003-09-15 18:59:46.000000', NULL, 1),
(420007, 37639, 8970, '<td valign="top">For focus on the woman, she needs to be in muc better focus.  The composition is nice.</td>', 'For focus on the woman, she needs to be in muc better focus.  The composition is nice.', '2003-09-15 19:05:45.000000', NULL, 1),
(420010, 37783, 8970, '<td valign="top">Removing the ball and the peoples heads was a very poor idea.  This image would have been fine showing the people.</td>', 'Removing the ball and the peoples heads was a very poor idea.  This image would have been fine showing the people.', '2003-09-15 19:06:54.000000', NULL, 1),
(420012, 37460, 6624, '<td valign="top">nice hand-tied fly and interesting light</td>', 'nice hand-tied fly and interesting light', '2003-09-15 19:07:55.000000', NULL, 1),
(420075, 37807, 6667, '<td valign="top">Wow! That''s right in there.  Nice</td>', 'Wow! That''s right in there.  Nice', '2003-09-15 20:30:18.000000', NULL, 1),
(420082, 37580, 7706, '<td valign="top">Hey love it, (since I am an Australian lol). Too bad about the team colors though. I think its great to see this sport represented here, esp from outside Australia. Good job.</td>', 'Hey love it, (since I am an Australian lol). Too bad about the team colors though. I think its great to see this sport represented here, esp from outside Australia. Good job.', '2003-09-15 20:41:30.000000', NULL, 1),
(420084, 37743, 6667, '<td valign="top">Free dive? Not with a regulator!</td>', 'Free dive? Not with a regulator!', '2003-09-15 20:42:41.000000', NULL, 1),
(420085, 37812, 6667, '<td valign="top">I hope you were referring to the bowling alley. . . not in the gutter!</td>', 'I hope you were referring to the bowling alley. . . not in the gutter!', '2003-09-15 20:44:27.000000', NULL, 1),
(420087, 37460, 6667, '<td valign="top">I would rather see the action. Nice fly.</td>', 'I would rather see the action. Nice fly.', '2003-09-15 20:46:47.000000', NULL, 1),
(420088, 37616, 6667, '<td valign="top">Lordy! This should have been a nostalgia entry.  I remember them all too well. Nicely done.  I just wish the kicker was more in focus.</td>', 'Lordy! This should have been a nostalgia entry.  I remember them all too well. Nicely done.  I just wish the kicker was more in focus.', '2003-09-15 20:49:59.000000', NULL, 1),
(420090, 37495, 772, '<td valign="top">Interesting photo but I can''t say that the exposure was optimal.</td>', 'Interesting photo but I can''t say that the exposure was optimal.', '2003-09-15 20:51:33.000000', NULL, 1),
(420091, 37763, 772, '<td valign="top">very tough job to expose this one correctly.  White objects in the light usually get blown out.</td>', 'very tough job to expose this one correctly.  White objects in the light usually get blown out.', '2003-09-15 20:52:42.000000', NULL, 1),
(420094, 37294, 6667, '<td valign="top">Kicking what?</td>', 'Kicking what?', '2003-09-15 20:59:19.000000', NULL, 1),
(420102, 37558, 7778, '<td valign="top">Persiflage. I commend the author of this image for submitting it, not because it''s a technical powerhouse of a photo, but because it demonstrates a sharp sense of humour and a keen eye for that which makes it work.<br/> <br/>The somewhat hapless composition and an, apparently, incidental -technique- give the impression of a snapshot taken for no other purpose as to make us laugh., at which task this capture exceeds. The range of the banter, however, is probably limited to the context of DPC.<br/> <br/>I cannot help but laugh with it.  &gt; 6</td>', 'Persiflage. I commend the author of this image for submitting it, not because it''s a technical powerhouse of a photo, but because it demonstrates a sharp sense of humour and a keen eye for that which makes it work. The somewhat hapless composition and an, apparently, incidental -technique- give the impression of a snapshot taken for no other purpose as to make us laugh., at which task this capture exceeds. The range of the banter, however, is probably limited to the context of DPC. I cannot help but laugh with it.  > 6', '2003-09-15 21:21:57.000000', NULL, 1),
(420103, 37417, 1379, '<td valign="top">I absolutely love this image.  The posture of your poor protagonist is perfect, and his dark clothing and long, lonesome shadow add to the distance from the other children.  I hope you listed this one as "emotive."  Awesome photo, and I hope he got to play.</td>', 'I absolutely love this image.  The posture of your poor protagonist is perfect, and his dark clothing and long, lonesome shadow add to the distance from the other children.  I hope you listed this one as "emotive."  Awesome photo, and I hope he got to play.', '2003-09-15 21:25:24.000000', NULL, 1),
(420115, 37763, 342, '<td valign="top">So, how many people told you the golf ball was over exposed?</td>', 'So, how many people told you the golf ball was over exposed?', '2003-09-15 21:45:47.000000', NULL, 1),
(420126, 37807, 11506, '<td valign="top">Wow, NICE SHOT!  9</td>', 'Wow, NICE SHOT!  9', '2003-09-15 22:02:44.000000', NULL, 1),
(420132, 37639, 10686, '<td valign="top">Good idea, but the picture is too soft</td>', 'Good idea, but the picture is too soft', '2003-09-15 22:16:29.000000', NULL, 1),
(420165, 37763, 259, '<td valign="top">very funny.  the ball seems a bit too bright, but other than that i like it.  nice shot.</td>', 'very funny.  the ball seems a bit too bright, but other than that i like it.  nice shot.', '2003-09-15 23:34:44.000000', NULL, 1),
(420166, 37684, 259, '<td valign="top">i think i tighter crop would improve the overall look.  although its not bad as it is.</td>', 'i think i tighter crop would improve the overall look.  although its not bad as it is.', '2003-09-15 23:36:06.000000', NULL, 1),
(420168, 37613, 259, '<td valign="top">i never thought i would see so many field hockey shots.  very nice job of catching action.</td>', 'i never thought i would see so many field hockey shots.  very nice job of catching action.', '2003-09-15 23:37:47.000000', NULL, 1),
(420173, 37643, 259, '<td valign="top">i really like this shot.  the only advice i have even though there is nothing you could really do about it, is that the left arm looks like it is missing at first and its the only very blurred part of the player as a whole which makes it kinda distracting.  however, i still feel this should be a top shot this week.</td>', 'i really like this shot.  the only advice i have even though there is nothing you could really do about it, is that the left arm looks like it is missing at first and its the only very blurred part of the player as a whole which makes it kinda distracting.  however, i still feel this should be a top shot this week.', '2003-09-15 23:41:04.000000', NULL, 1),
(420175, 37842, 259, '<td valign="top">wow, very impressive</td>', 'wow, very impressive', '2003-09-15 23:42:27.000000', NULL, 1),
(420178, 37426, 4494, '<td valign="top">Very nice capturing the ball falling into the hole.</td>', 'Very nice capturing the ball falling into the hole.', '2003-09-15 23:43:44.000000', NULL, 1),
(420181, 37748, 259, '<td valign="top">although the kid is straight, the wall is very angled and the yellow line doesnt help to hide it either.  compositionaly the picture is very good with the kid looking toward the empty part of the picture which i really like.</td>', 'although the kid is straight, the wall is very angled and the yellow line doesnt help to hide it either.  compositionaly the picture is very good with the kid looking toward the empty part of the picture which i really like.', '2003-09-15 23:45:37.000000', NULL, 1),
(420182, 37842, 4494, '<td valign="top">Awesome picture.  The winner so far. :)  I love the lighting and great sense of motion.  8.</td>', 'Awesome picture.  The winner so far. :)  I love the lighting and great sense of motion.  8.', '2003-09-15 23:46:34.000000', NULL, 1),
(420183, 37471, 259, '<td valign="top">very nice colors, the green is great.</td>', 'very nice colors, the green is great.', '2003-09-15 23:47:19.000000', NULL, 1),
(420184, 37824, 4494, '<td valign="top">I don''t know if I like the foot in the shot or not.  I guess it adds a little more interest.  Nice "crisp" image, great DOF.</td>', 'I don''t know if I like the foot in the shot or not.  I guess it adds a little more interest.  Nice "crisp" image, great DOF.', '2003-09-15 23:48:30.000000', NULL, 1),
(420185, 37007, 3102, '<td valign="top">I''m honestly not fond of the description in the title -- it would have been best to simply call it "Screen Pass" and let that be that.  Otherwise, I like the shot a lot, especially his expression.  I''m not sure I am sold on the crop...  I may have tried doing this as a horizontal shot that includes just the ball, his face and more of the shoulders.  Seems like there''s too much headroom and unnecessary space below his left elbow.  Great depth of field, I might add!</td>', 'I''m honestly not fond of the description in the title -- it would have been best to simply call it "Screen Pass" and let that be that.  Otherwise, I like the shot a lot, especially his expression.  I''m not sure I am sold on the crop...  I may have tried doing this as a horizontal shot that includes just the ball, his face and more of the shoulders.  Seems like there''s too much headroom and unnecessary space below his left elbow.  Great depth of field, I might add!', '2003-09-15 23:48:34.000000', NULL, 1),
(420186, 37835, 259, '<td valign="top">i never thought i would see so many field hockey shots.  i really like this shot a lot.  it has so much intensity.</td>', 'i never thought i would see so many field hockey shots.  i really like this shot a lot.  it has so much intensity.', '2003-09-15 23:48:38.000000', NULL, 1),
(420188, 37595, 259, '<td valign="top">the landscape seems more dominate than the sport, but never the less, its a great shot.</td>', 'the landscape seems more dominate than the sport, but never the less, its a great shot.', '2003-09-15 23:49:59.000000', NULL, 1),
(420189, 37265, 4494, '<td valign="top">Pretty cool.  How did you do this?  Invert and then blue toning?  The black background and offset double image makes it really cool.</td>', 'Pretty cool.  How did you do this?  Invert and then blue toning?  The black background and offset double image makes it really cool.', '2003-09-15 23:50:05.000000', NULL, 1),
(420190, 37736, 4494, '<td valign="top">It appears to be a little dark for my taste, but still very good.  Super sharp image.  Just need to use Levels or Curves on it I think.</td>', 'It appears to be a little dark for my taste, but still very good.  Super sharp image.  Just need to use Levels or Curves on it I think.', '2003-09-15 23:51:18.000000', NULL, 1),
(420192, 37009, 259, '<td valign="top">i really like the contrast between the red and black.</td>', 'i really like the contrast between the red and black.', '2003-09-15 23:52:31.000000', NULL, 1),
(420194, 37760, 259, '<td valign="top">i love all the negative space.</td>', 'i love all the negative space.', '2003-09-15 23:53:19.000000', NULL, 1),
(420195, 37763, 4494, '<td valign="top">Hahaha, that''s a tough shot. :)  The ball is a little blown out in the color on the top.</td>', 'Hahaha, that''s a tough shot. :)  The ball is a little blown out in the color on the top.', '2003-09-15 23:53:51.000000', NULL, 1),
(420200, 37736, 6597, '<td valign="top">I like the texture of the water  7</td>', 'I like the texture of the water  7', '2003-09-15 23:59:06.000000', NULL, 1),
(420202, 37335, 6597, '<td valign="top">I don''t see any action</td>', 'I don''t see any action', '2003-09-15 23:59:40.000000', NULL, 1),
(420203, 37558, 4494, '<td valign="top">LOL, what''s really funny about this is the Gatorade, towel, and how the player looks like he''s sweating!  Hahahaaa, great.  But the pic itself needs better lighting, etc.  Creative shot.  6.</td>', 'LOL, what''s really funny about this is the Gatorade, towel, and how the player looks like he''s sweating!  Hahahaaa, great.  But the pic itself needs better lighting, etc.  Creative shot.  6.', '2003-09-16 00:00:23.000000', NULL, 1),
(420209, 36920, 6597, '<td valign="top">good composition plenty of action 9</td>', 'good composition plenty of action 9', '2003-09-16 00:01:50.000000', NULL, 1),
(420210, 37812, 4494, '<td valign="top">Two things:  1) It''s tilted WAY to far to the left.  This is such a basic problem, I''m surprised how many people don''t even notice it.  2) You should have lowered your angle to maybe a foot off the floor.  That would give it a much better perspective.  I like the colors in the shot however.</td>', 'Two things:  1) It''s tilted WAY to far to the left.  This is such a basic problem, I''m surprised how many people don''t even notice it.  2) You should have lowered your angle to maybe a foot off the floor.  That would give it a much better perspective.  I like the colors in the shot however.', '2003-09-16 00:02:30.000000', NULL, 1),
(420212, 37807, 6597, '<td valign="top">I like the close up effect hope surfer is ok  9<br/>                                                     Se</td>', 'I like the close up effect hope surfer is ok  9                                                     Se', '2003-09-16 00:04:04.000000', NULL, 1),
(420213, 37829, 4494, '<td valign="top">Beautiful shot.  I love the subject and tone of it... But, Chess isn''t really a sport so IMO it doesn''t fit the challenge. :(  But you get a higher score because I like the shot. :)</td>', 'Beautiful shot.  I love the subject and tone of it... But, Chess isn''t really a sport so IMO it doesn''t fit the challenge. :(  But you get a higher score because I like the shot. :)', '2003-09-16 00:04:38.000000', NULL, 1),
(420214, 37808, 4494, '<td valign="top">LOL, I love the Title. :)</td>', 'LOL, I love the Title. :)', '2003-09-16 00:06:04.000000', NULL, 1),
(420215, 37648, 4494, '<td valign="top">Nice shot.  The white is a little blown out, but nice focus and "concentration" on the subject.  You should have tilted it to the right about 5 degrees.  This would make the ppl in the background upright and give the subject the appearance of runner forward a little more.</td>', 'Nice shot.  The white is a little blown out, but nice focus and "concentration" on the subject.  You should have tilted it to the right about 5 degrees.  This would make the ppl in the background upright and give the subject the appearance of runner forward a little more.', '2003-09-16 00:07:49.000000', NULL, 1),
(420216, 37825, 4494, '<td valign="top">Too bad those kids are in the pic.  Would be fantastic without them there.  Still good.  The exposure and panning is perfect.</td>', 'Too bad those kids are in the pic.  Would be fantastic without them there.  Still good.  The exposure and panning is perfect.', '2003-09-16 00:09:30.000000', NULL, 1),
(420217, 37717, 4494, '<td valign="top">Those rodeo guys are craaaazy. :)  That looks like the clown getting mowed over.  The pic is a little small, try making it bigger.</td>', 'Those rodeo guys are craaaazy. :)  That looks like the clown getting mowed over.  The pic is a little small, try making it bigger.', '2003-09-16 00:11:33.000000', NULL, 1),
(420219, 37834, 4494, '<td valign="top">LOL, don''t get in his way.</td>', 'LOL, don''t get in his way.', '2003-09-16 00:12:20.000000', NULL, 1),
(420220, 37042, 4494, '<td valign="top">Great shot!  You captured the action nicely.  To bad you can''t see the barrel, but still good.</td>', 'Great shot!  You captured the action nicely.  To bad you can''t see the barrel, but still good.', '2003-09-16 00:13:07.000000', NULL, 1),
(420221, 37783, 4494, '<td valign="top">What the?  Doesn''t look legal.</td>', 'What the?  Doesn''t look legal.', '2003-09-16 00:16:05.000000', NULL, 1),
(420222, 37007, 4494, '<td valign="top">Looks staged like he''s just holding the ball with his finger tips, although reading your Title I''ll give you the benefit of the doubt.  Actually the "flexing" of the arm muscles kinda suggests it is NOT staged.  Great shot!!  You DID get lucky, awesome shot.   8.<br/></td>', 'Looks staged like he''s just holding the ball with his finger tips, although reading your Title I''ll give you the benefit of the doubt.  Actually the "flexing" of the arm muscles kinda suggests it is NOT staged.  Great shot!!  You DID get lucky, awesome shot.   8.', '2003-09-16 00:21:46.000000', NULL, 1),
(420224, 37595, 4494, '<td valign="top">Wow that is sooo great looking.</td>', 'Wow that is sooo great looking.', '2003-09-16 00:22:40.000000', NULL, 1),
(420228, 37639, 4494, '<td valign="top">Looks a little blury.  Nice B&amp;W toning however.</td>', 'Looks a little blury.  Nice B&W toning however.', '2003-09-16 00:28:24.000000', NULL, 1),
(420230, 37417, 4494, '<td valign="top">What is REALLY cool about this pic, is the boy (subject) is dressed in black (or blue?) and really stands out nicely from the others.  To make it even better, you should have used a larger aprature (less DOF) to make the kids in the background a little more blurry.</td>', 'What is REALLY cool about this pic, is the boy (subject) is dressed in black (or blue?) and really stands out nicely from the others.  To make it even better, you should have used a larger aprature (less DOF) to make the kids in the background a little more blurry.', '2003-09-16 00:30:59.000000', NULL, 1),
(420231, 37330, 4967, '<td valign="top">The lighting here is very cool... and the action of that one moving pawn is great :-)  I''m not sure how you did that (a string?) without using your fingers but it''s pretty cool,  Looks like they are moving on their own accord, hence playing a sport :-)  I like your spotlighting effect here, very nicely done.  This is a good artsy take on sports challenge.  I can''t decide whether it is a sport or not, but I was kind of looking for human interaction (thats my point of view) still a solid -8- though.  nice job :-)</td>', 'The lighting here is very cool... and the action of that one moving pawn is great :-)  I''m not sure how you did that (a string?) without using your fingers but it''s pretty cool,  Looks like they are moving on their own accord, hence playing a sport :-)  I like your spotlighting effect here, very nicely done.  This is a good artsy take on sports challenge.  I can''t decide whether it is a sport or not, but I was kind of looking for human interaction (thats my point of view) still a solid -8- though.  nice job :-)', '2003-09-16 00:31:51.000000', NULL, 1),
(420234, 36920, 9441, '<td valign="top">Excellent view and shot!  How''d you accomplish this angle?  It''s wonderful!</td>', 'Excellent view and shot!  How''d you accomplish this angle?  It''s wonderful!', '2003-09-16 00:41:35.000000', NULL, 1),
