(420345, 37643, 9073, '<td valign="top">All of the key ingredients for a good sports shot are here. This one''s going for a ribbon.</td>', 'All of the key ingredients for a good sports shot are here. This one''s going for a ribbon.', '2003-09-16 02:41:59.000000', NULL, 1),
(420352, 36920, 9073, '<td valign="top">Very, very good. You''ve captured the waves excellently.</td>', 'Very, very good. You''ve captured the waves excellently.', '2003-09-16 02:51:20.000000', NULL, 1),
(420353, 37807, 9073, '<td valign="top">Wonderful action shot.</td>', 'Wonderful action shot.', '2003-09-16 02:52:42.000000', NULL, 1),
(420355, 37810, 9073, '<td valign="top">Interesting take on the challenge. The choice of b&amp;w and the iconography work well to convey your message of a corporate, mindless media-controlled culture. However, I find this photo visually uninteresting beyond its referential meaning.</td>', 'Interesting take on the challenge. The choice of b&w and the iconography work well to convey your message of a corporate, mindless media-controlled culture. However, I find this photo visually uninteresting beyond its referential meaning.', '2003-09-16 02:58:28.000000', NULL, 1),
(420356, 37812, 9073, '<td valign="top">This would have been much better if you''d taken a shot of her actually throwing a ball....</td>', 'This would have been much better if you''d taken a shot of her actually throwing a ball....', '2003-09-16 03:01:41.000000', NULL, 1),
(420360, 37852, 9073, '<td valign="top">I can see your idea of using a circular motive here. However, the final effect isn''t very inspiring. Sorry.</td>', 'I can see your idea of using a circular motive here. However, the final effect isn''t very inspiring. Sorry.', '2003-09-16 03:13:33.000000', NULL, 1),
(420365, 37825, 9073, '<td valign="top">Very skillful capture here. A ribbon, or close to it, I''m sure.</td>', 'Very skillful capture here. A ribbon, or close to it, I''m sure.', '2003-09-16 03:16:01.000000', NULL, 1),
(420367, 37563, 9073, '<td valign="top">Good action. No2 interests me with her slightly gawkish expression.</td>', 'Good action. No2 interests me with her slightly gawkish expression.', '2003-09-16 03:25:20.000000', NULL, 1),
(420394, 37825, 11457, '<td valign="top">The motion blur in the background is very effective in isolating the subject and conveying his lonely effort and his concentration. I like the shadow of the bicycle, too, and the overall composition.</td>', 'The motion blur in the background is very effective in isolating the subject and conveying his lonely effort and his concentration. I like the shadow of the bicycle, too, and the overall composition.', '2003-09-16 05:52:47.000000', NULL, 1),
