(420398, 37824, 4500, '<td valign="top">The only not overexposed golf ball in this challenge. Great shot, perfect DOF</td>', 'The only not overexposed golf ball in this challenge. Great shot, perfect DOF', '2003-09-16 06:50:44.000000', NULL, 1),
(420407, 37596, 10705, '<td valign="top">Great action shot ... nice capture.   I think the shadow adds a lot of interest.</td>', 'Great action shot ... nice capture.   I think the shadow adds a lot of interest.', '2003-09-16 08:29:49.000000', NULL, 1),
