(420543, 37745, 3102, '<td valign="top">Looks like the work of cimarron98!</td>', 'Looks like the work of cimarron98!', '2003-09-16 11:39:00.000000', NULL, 1),
(420544, 37648, 3102, '<td valign="top">Great depth of field, and a wonderful expression of determination!</td>', 'Great depth of field, and a wonderful expression of determination!', '2003-09-16 11:40:44.000000', NULL, 1),
(420545, 37842, 5475, '<td valign="top">Awesome!!  This is my favorite shot in the Sports challenge!  I''ve logged many miles on my trainer,  and I wish I had a shot like this!  Excellent work!    Good luck in the challenge.  10 from me!<br/>JD Anderson</td>', 'Awesome!!  This is my favorite shot in the Sports challenge!  I''ve logged many miles on my trainer,  and I wish I had a shot like this!  Excellent work!    Good luck in the challenge.  10 from me!JD Anderson', '2003-09-16 11:49:55.000000', NULL, 1),
(420549, 37558, 5475, '<td valign="top">Crack me up!  I gave this a 10 for making me laugh out loud.  Who''s up for a little Full Contact Chess?  This reminds me of the time I spent in Kansas with my cousins.  They do everything full contact, basket ball, tennis, video games, dinner...  You name it, it was fair game.  I don''t think I ever got a fat lip at dinner, except there with my cousins and uncle!  The towel and Gatorade bottle, not to mention the "in your face" pose/expression are great!  Nice work!<br/>JD Anderson</td>', 'Crack me up!  I gave this a 10 for making me laugh out loud.  Who''s up for a little Full Contact Chess?  This reminds me of the time I spent in Kansas with my cousins.  They do everything full contact, basket ball, tennis, video games, dinner...  You name it, it was fair game.  I don''t think I ever got a fat lip at dinner, except there with my cousins and uncle!  The towel and Gatorade bottle, not to mention the "in your face" pose/expression are great!  Nice work!JD Anderson', '2003-09-16 11:54:23.000000', NULL, 1),
(420641, 37810, 8250, '<td valign="top">not sure if this meets the challenge lol but i like it, i like the contrast of your pic its great</td>', 'not sure if this meets the challenge lol but i like it, i like the contrast of your pic its great', '2003-09-16 14:53:04.000000', NULL, 1),
(420643, 37294, 8250, '<td valign="top">its so hard to photo an event like this but you dont seem to have any problems well done mate</td>', 'its so hard to photo an event like this but you dont seem to have any problems well done mate', '2003-09-16 14:53:40.000000', NULL, 1),
