(420667, 37760, 7969, '<td valign="top">The textures and form of the man on the left is wonderful.  Great composition and a very creative take on this challenge.</td>', 'The textures and form of the man on the left is wonderful.  Great composition and a very creative take on this challenge.', '2003-09-16 15:46:36.000000', NULL, 1),
(420668, 37834, 7969, '<td valign="top">The boy in the air is great!  Especially that he is barefoot.  NIce job.</td>', 'The boy in the air is great!  Especially that he is barefoot.  NIce job.', '2003-09-16 15:48:53.000000', NULL, 1),
(420670, 37736, 7969, '<td valign="top">Great sharp and clear image, good composition too.<br/></td>', 'Great sharp and clear image, good composition too.', '2003-09-16 15:50:02.000000', NULL, 1),
(420672, 37835, 7969, '<td valign="top">Great facial expressions!</td>', 'Great facial expressions!', '2003-09-16 15:51:24.000000', NULL, 1),
(420690, 37594, 9550, '<td valign="top">Awsome Photo. My favorite. Good choice on the Sepia tone! (Would like to see it in colour) I would have done without the border. Great comosition. 10</td>', 'Awsome Photo. My favorite. Good choice on the Sepia tone! (Would like to see it in colour) I would have done without the border. Great comosition. 10', '2003-09-16 16:21:35.000000', NULL, 1),
(420698, 37751, 9550, '<td valign="top">Not very good composition! The colour and lighting are very good. Nice shadows behind the mouth-piece. I would have taken this at an angle where you can see the tooth prints in the mouth-piece its self.<br/></td>', 'Not very good composition! The colour and lighting are very good. Nice shadows behind the mouth-piece. I would have taken this at an angle where you can see the tooth prints in the mouth-piece its self.', '2003-09-16 16:25:27.000000', NULL, 1),
(420699, 37801, 9550, '<td valign="top">Great composition, wonderful colours, great motion capture! 10</td>', 'Great composition, wonderful colours, great motion capture! 10', '2003-09-16 16:27:27.000000', NULL, 1),
(420700, 37552, 9550, '<td valign="top">I like the panorama crop. Good composition,great colour, good motion capture. 10</td>', 'I like the panorama crop. Good composition,great colour, good motion capture. 10', '2003-09-16 16:28:39.000000', NULL, 1),
(420701, 37417, 9550, '<td valign="top">Awsome photo. Really Emotive! Good choice of B&amp;W. I belive the rule of thirds played a big part in this. 10</td>', 'Awsome photo. Really Emotive! Good choice of B&W. I belive the rule of thirds played a big part in this. 10', '2003-09-16 16:30:36.000000', NULL, 1),
(420703, 37596, 9550, '<td valign="top">A little motin blur. But what do you expect from a great motion capture. The shadow gives it a 3-D effect. Good composition. 10</td>', 'A little motin blur. But what do you expect from a great motion capture. The shadow gives it a 3-D effect. Good composition. 10', '2003-09-16 16:32:53.000000', NULL, 1),
(420755, 37807, 10625, '<td valign="top">right on! good luck.</td>', 'right on! good luck.', '2003-09-16 17:53:33.000000', NULL, 1),
(420766, 37616, 12272, '<td valign="top">yaeh pretty cool</td>', 'yaeh pretty cool', '2003-09-16 18:19:08.000000', NULL, 1),
(420768, 37417, 11872, '<td valign="top">I love it. you really managed to capture the feeling of dissapointment. nicely done</td>', 'I love it. you really managed to capture the feeling of dissapointment. nicely done', '2003-09-16 18:20:58.000000', NULL, 1),
(420876, 37596, 11738, '<td valign="top">I find the frame is a bit much for such an action shot.  I would have used a simpler border.  Nice shot of a nice dog!</td>', 'I find the frame is a bit much for such an action shot.  I would have used a simpler border.  Nice shot of a nice dog!', '2003-09-16 21:11:56.000000', NULL, 1),
(420879, 37825, 11738, '<td valign="top">I love how you froze the primary subject while giving the feeling of speed.  Were you in a vehicle when you took this shot?</td>', 'I love how you froze the primary subject while giving the feeling of speed.  Were you in a vehicle when you took this shot?', '2003-09-16 21:13:23.000000', NULL, 1),
(420880, 37007, 11738, '<td valign="top">This image would have been better if the fit wasn"t so tight around the subject.  Excellent focus and exquisite timing.  Awesome shot!</td>', 'This image would have been better if the fit wasn"t so tight around the subject.  Excellent focus and exquisite timing.  Awesome shot!', '2003-09-16 21:15:28.000000', NULL, 1),
(420882, 37715, 11738, '<td valign="top">Neat image but I find that not enough was cropped off the bottom.  Good action shot.</td>', 'Neat image but I find that not enough was cropped off the bottom.  Good action shot.', '2003-09-16 21:17:19.000000', NULL, 1),
(420887, 37634, 11738, '<td valign="top">I love the expressions you captured on this shot!  Good job</td>', 'I love the expressions you captured on this shot!  Good job', '2003-09-16 21:22:06.000000', NULL, 1),
(420891, 37763, 11738, '<td valign="top">Interesting shot, but the golf ball seems a bit overexposed.  I would HATE to play that lie! :-(</td>', 'Interesting shot, but the golf ball seems a bit overexposed.  I would HATE to play that lie! :-(', '2003-09-16 21:31:27.000000', NULL, 1),
(420927, 37238, 7763, '<td valign="top">super photo!</td>', 'super photo!', '2003-09-16 22:22:47.000000', NULL, 1),
