(421601, 37842, 2883, '<td valign="top">This would make a great Shimano add. Great effect and use of lighting.</td>', 'This would make a great Shimano add. Great effect and use of lighting.', '2003-09-17 11:17:10.000000', NULL, 1),
(421604, 37330, 2883, '<td valign="top">Wonderful lighting. I think as a photo it would be better without the motion blur, but then, action is suppose to be shown, so well done.</td>', 'Wonderful lighting. I think as a photo it would be better without the motion blur, but then, action is suppose to be shown, so well done.', '2003-09-17 11:18:26.000000', NULL, 1),
(421607, 37471, 2883, '<td valign="top">The lighting is a little bright, but the action, colors and angle are wonderful.</td>', 'The lighting is a little bright, but the action, colors and angle are wonderful.', '2003-09-17 11:19:09.000000', NULL, 1),
(421711, 37524, 4517, '<td valign="top">Looks like it`s in the 25.</td>', 'Looks like it`s in the 25.', '2003-09-17 12:40:37.000000', NULL, 1),
(421837, 37685, 5491, '<td valign="top">I don''t really dig how this photo was cropped. It could also stand to be a tad brighter. When I think of racing of any kind I think of bright vivid colors and this photo just doesn''t have that.</td>', 'I don''t really dig how this photo was cropped. It could also stand to be a tad brighter. When I think of racing of any kind I think of bright vivid colors and this photo just doesn''t have that.', '2003-09-17 13:45:23.000000', NULL, 1),
(421839, 37684, 5491, '<td valign="top">Decent shot but there''s nothing in this that conveys any sense of motion. It''s almost as if he was posing with the paddle in the water.</td>', 'Decent shot but there''s nothing in this that conveys any sense of motion. It''s almost as if he was posing with the paddle in the water.', '2003-09-17 13:46:20.000000', NULL, 1),
(421840, 37643, 5491, '<td valign="top">I think I would have cropped this so that the player''s legs on the right weren''t visible. They''re kind of distracting to me.</td>', 'I think I would have cropped this so that the player''s legs on the right weren''t visible. They''re kind of distracting to me.', '2003-09-17 13:46:58.000000', NULL, 1),
(421841, 37007, 5491, '<td valign="top">Maybe a little cropping at the top wouldn''t have hurt though? Great photo otherwise.  7</td>', 'Maybe a little cropping at the top wouldn''t have hurt though? Great photo otherwise.  7', '2003-09-17 13:47:36.000000', NULL, 1),
(421842, 37294, 5491, '<td valign="top">A few seconds earlier with the ball in the photo might have added a little something extra...  6</td>', 'A few seconds earlier with the ball in the photo might have added a little something extra...  6', '2003-09-17 13:48:04.000000', NULL, 1),
(421846, 37596, 5491, '<td valign="top">Maybe a little tighter crop on the top and left and a little lower on the bottom to include the entire shadow?</td>', 'Maybe a little tighter crop on the top and left and a little lower on the bottom to include the entire shadow?', '2003-09-17 13:49:12.000000', NULL, 1),
(421848, 37824, 5491, '<td valign="top">I''ve seen way too many shots like this elsewhere. I''d like to see one of the moment of impact though, now that would be a photo.</td>', 'I''ve seen way too many shots like this elsewhere. I''d like to see one of the moment of impact though, now that would be a photo.', '2003-09-17 13:50:00.000000', NULL, 1),
(421849, 37634, 5491, '<td valign="top">Looks like these kids were just force fed castor oil.  hah Great shot. 7</td>', 'Looks like these kids were just force fed castor oil.  hah Great shot. 7', '2003-09-17 13:51:01.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(421919, 37842, 4967, '<td valign="top">This is really quite cool.  I''m curious how you caught this, how much you cropped, if this person was actually cycling by etc.   avery unique sports shot indeed :-)  Great composition, everything is very well done, I would have liked it maybe a little brighter but I understand that probably wasn''t possible.  Was the bike stationary?  I don''t know how you could get it otherwise.  I''m going for a -9- on this shot.  Well done!</td>', 'This is really quite cool.  I''m curious how you caught this, how much you cropped, if this person was actually cycling by etc.   avery unique sports shot indeed :-)  Great composition, everything is very well done, I would have liked it maybe a little brighter but I understand that probably wasn''t possible.  Was the bike stationary?  I don''t know how you could get it otherwise.  I''m going for a -9- on this shot.  Well done!', '2003-09-17 15:08:42.000000', NULL, 1),
(421921, 37582, 4967, '<td valign="top">What beautiful animals!  This looks like it was right before a race, I''m curious why you chose to go with this photo instead of a real action picture of the race.  I find this one to be somewhat bland.  I also am not very keen on your title.  But thats just me.</td>', 'What beautiful animals!  This looks like it was right before a race, I''m curious why you chose to go with this photo instead of a real action picture of the race.  I find this one to be somewhat bland.  I also am not very keen on your title.  But thats just me.', '2003-09-17 15:10:04.000000', NULL, 1),
(421923, 37558, 4967, '<td valign="top">Hehehehe good job turning chess into a "real sport " ;-)  Really funny idea with the sports towel and the gatorade.  I would have cropped off a lot of the extraneous space at the top and maybe some of the left side?  Fun though.</td>', 'Hehehehe good job turning chess into a "real sport " ;-)  Really funny idea with the sports towel and the gatorade.  I would have cropped off a lot of the extraneous space at the top and maybe some of the left side?  Fun though.', '2003-09-17 15:11:29.000000', NULL, 1),
(421926, 37783, 4967, '<td valign="top">I''m not sure how you achieved this in camera but i don''t really like what happened to it.  I  just don''t really find this to be an amusing, or attractive photo, and it just doesn''t look good to me.  This might have had the makings of a good sports photo if you didn''t have the weird things on it.  Sorry.</td>', 'I''m not sure how you achieved this in camera but i don''t really like what happened to it.  I  just don''t really find this to be an amusing, or attractive photo, and it just doesn''t look good to me.  This might have had the makings of a good sports photo if you didn''t have the weird things on it.  Sorry.', '2003-09-17 15:13:05.000000', NULL, 1),
(421928, 37763, 4967, '<td valign="top">Amusing.  I can''t really see this as having action though, and would consider it to be more of a humorous or still life photo.  Technically I like the composition, however the ball is extremely blown out and it bothers me that you can''t make out any detail, let alone barely being able to see the name on it.</td>', 'Amusing.  I can''t really see this as having action though, and would consider it to be more of a humorous or still life photo.  Technically I like the composition, however the ball is extremely blown out and it bothers me that you can''t make out any detail, let alone barely being able to see the name on it.', '2003-09-17 15:15:30.000000', NULL, 1),
(421935, 37294, 4967, '<td valign="top">Funny title.  amusing shot, however I guess I don''t really find this to be a great sports shot, because of the lack of a ball, had there been a ball in the photo this would have been much better.  I like the expressions though and especially "Katie" Just wish there was a ball in there...</td>', 'Funny title.  amusing shot, however I guess I don''t really find this to be a great sports shot, because of the lack of a ball, had there been a ball in the photo this would have been much better.  I like the expressions though and especially "Katie" Just wish there was a ball in there...', '2003-09-17 15:19:11.000000', NULL, 1),
(421941, 37824, 4967, '<td valign="top">I like the idea here... however to make this more effective I might have gone for an obvious swing to the golf club, slowing the shutter quite a bit would have been really cool, although challenging to get the shot it would have really added to the action of this photo.  As it is it just looks like the club is sitting still on the grass right behind the ball.  I love your DOF though.  Also nice job leaving room in the photo for the ball to travel.  -7-</td>', 'I like the idea here... however to make this more effective I might have gone for an obvious swing to the golf club, slowing the shutter quite a bit would have been really cool, although challenging to get the shot it would have really added to the action of this photo.  As it is it just looks like the club is sitting still on the grass right behind the ball.  I love your DOF though.  Also nice job leaving room in the photo for the ball to travel.  -7-', '2003-09-17 15:20:54.000000', NULL, 1),
(422074, 37134, 12303, '<td valign="top">great but not too sharp</td>', 'great but not too sharp', '2003-09-17 16:45:20.000000', NULL, 1),
(422091, 37330, 12104, '<td valign="top">very nice shot<br/>it really seems to be like an army</td>', 'very nice shotit really seems to be like an army', '2003-09-17 17:01:19.000000', NULL, 1),
(422108, 37552, 778, '<td valign="top">Baseball at its best!  Great capture.  My only 10!  You captured the colors, action and meaning of the sport!  Not sure if the cropping works all that well for me...but all-in-all the best of the bunch!</td>', 'Baseball at its best!  Great capture.  My only 10!  You captured the colors, action and meaning of the sport!  Not sure if the cropping works all that well for me...but all-in-all the best of the bunch!', '2003-09-17 17:13:02.000000', NULL, 1),
