(423876, 37697, 2883, '<td valign="top">The overall photo could be a little better focused. Good capture of action though.</td>', 'The overall photo could be a little better focused. Good capture of action though.', '2003-09-19 11:13:11.000000', NULL, 1),
(423877, 37009, 2883, '<td valign="top">I like the theme of the photo. It seems that the overall photo could be sharper. Good coloring.</td>', 'I like the theme of the photo. It seems that the overall photo could be sharper. Good coloring.', '2003-09-19 11:14:52.000000', NULL, 1),
(423930, 37596, 5792, '<td valign="top">Nice timing on this capture. Usually pet action shots are more like snapshots, but this one overcomes that. You can''t even see the wires holding up the dog. :)</td>', 'Nice timing on this capture. Usually pet action shots are more like snapshots, but this one overcomes that. You can''t even see the wires holding up the dog. :)', '2003-09-19 13:55:37.000000', NULL, 1),
(423931, 37007, 5792, '<td valign="top">Nice action capture, good framing and the soft focus background in very nice.</td>', 'Nice action capture, good framing and the soft focus background in very nice.', '2003-09-19 13:56:54.000000', NULL, 1),
(423933, 37824, 5792, '<td valign="top">Good use of very shallow DOF and solid framing and composition. This is a strong image. Nike will be pleased. :)</td>', 'Good use of very shallow DOF and solid framing and composition. This is a strong image. Nike will be pleased. :)', '2003-09-19 13:59:18.000000', NULL, 1),
(423934, 37635, 5792, '<td valign="top">Great action shot.</td>', 'Great action shot.', '2003-09-19 13:59:53.000000', NULL, 1),
(423935, 37750, 5792, '<td valign="top">Good capture, nice framing.</td>', 'Good capture, nice framing.', '2003-09-19 14:00:22.000000', NULL, 1),
(423936, 37634, 5792, '<td valign="top">Nice expressions. Soft background always works nice with sports images.</td>', 'Nice expressions. Soft background always works nice with sports images.', '2003-09-19 14:01:30.000000', NULL, 1),
(423938, 37330, 5792, '<td valign="top">Outstanding. Beautifully done image. The moving king pawn opening is a great touch. Lighting is spectacular. Framing is terrific. Hope this image is not hurt by those that think chess is "not sports". One of the best in this challenge.</td>', 'Outstanding. Beautifully done image. The moving king pawn opening is a great touch. Lighting is spectacular. Framing is terrific. Hope this image is not hurt by those that think chess is "not sports". One of the best in this challenge.', '2003-09-19 14:05:44.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(423939, 37471, 5792, '<td valign="top">Beautiful lighting, action and framing. Decent technical shot.</td>', 'Beautiful lighting, action and framing. Decent technical shot.', '2003-09-19 14:07:02.000000', NULL, 1),
(423941, 37812, 5792, '<td valign="top">Nice reflection off the lane and ball return. Given the position of the ball, I hope you are not commenting on your wife''s skill level as well. :)</td>', 'Nice reflection off the lane and ball return. Given the position of the ball, I hope you are not commenting on your wife''s skill level as well. :)', '2003-09-19 14:18:53.000000', NULL, 1),
(423950, 37568, 5792, '<td valign="top">Could have called this one "Three in the corner pocket".  Nice angle.</td>', 'Could have called this one "Three in the corner pocket".  Nice angle.', '2003-09-19 14:24:20.000000', NULL, 1),
(423965, 37829, 5792, '<td valign="top">Fisher thinking, "Take that, Spassky!"  Nice composition.</td>', 'Fisher thinking, "Take that, Spassky!"  Nice composition.', '2003-09-19 14:32:22.000000', NULL, 1),
(423972, 37810, 5792, '<td valign="top">A sport a lot of folks identify with. :)</td>', 'A sport a lot of folks identify with. :)', '2003-09-19 14:34:33.000000', NULL, 1),
(424145, 37635, 7758, '<td valign="top">Great capture, what can I say? 10 out of 10 from me. Good luck, Todd.</td>', 'Great capture, what can I say? 10 out of 10 from me. Good luck, Todd.', '2003-09-19 15:27:33.000000', NULL, 1),
(424149, 37787, 5792, '<td valign="top">Well composed and framed. Slight overexposure on the top of the strings. Good job.</td>', 'Well composed and framed. Slight overexposure on the top of the strings. Good job.', '2003-09-19 15:28:43.000000', NULL, 1),
(424169, 37558, 5792, '<td valign="top">Fun image. The gatorade and towel are nice touches. A cheerleader with a low cut top and nice pom poms would work well in this situation. :)<br/> <br/>However, if the king is on the black square it could move to N6 or aggressively to N4 to attack the knight, rook and pawn. With queen support and the black rook eventually taking whites rook black could easily get a draw and possibly win the game before white can advance its pawns.<br/> <br/>If the king is on the white square then it could still move to K6 to try and escape... but then it would only be a matter of time.<br/> <br/>Might still be early to pour gatorade over the coachs head.</td>', 'Fun image. The gatorade and towel are nice touches. A cheerleader with a low cut top and nice pom poms would work well in this situation. :) However, if the king is on the black square it could move to N6 or aggressively to N4 to attack the knight, rook and pawn. With queen support and the black rook eventually taking whites rook black could easily get a draw and possibly win the game before white can advance its pawns. If the king is on the white square then it could still move to K6 to try and escape... but then it would only be a matter of time. Might still be early to pour gatorade over the coachs head.', '2003-09-19 15:33:53.000000', NULL, 1),
(424203, 37294, 8125, '<td valign="top">Great stop action shot.  I wish I could''ve seen the ball as well.  Very nice shot!</td>', 'Great stop action shot.  I wish I could''ve seen the ball as well.  Very nice shot!', '2003-09-19 17:21:27.000000', NULL, 1),
(424207, 37807, 8125, '<td valign="top">Excellent shot!  Very well done....</td>', 'Excellent shot!  Very well done....', '2003-09-19 17:24:11.000000', NULL, 1),
(424209, 37835, 8125, '<td valign="top">Nice catch on this shot.  Very well done!</td>', 'Nice catch on this shot.  Very well done!', '2003-09-19 17:25:35.000000', NULL, 1),
(424211, 37007, 8125, '<td valign="top">Excellent catch (for both of you)!  :-)    Well framed, good lighting and clarity.  Nice job!</td>', 'Excellent catch (for both of you)!  :-)    Well framed, good lighting and clarity.  Nice job!', '2003-09-19 17:27:21.000000', NULL, 1),
(424212, 37769, 8125, '<td valign="top">I really like motorcross shots - this one is framed well, but a little out of focus.</td>', 'I really like motorcross shots - this one is framed well, but a little out of focus.', '2003-09-19 17:28:34.000000', NULL, 1),
(424214, 37009, 8125, '<td valign="top">Wow, nice catch!  I''d hate to be in the middle of that pile!</td>', 'Wow, nice catch!  I''d hate to be in the middle of that pile!', '2003-09-19 17:30:04.000000', NULL, 1),
(424216, 37643, 8125, '<td valign="top">This is a great shot.  I really feel the action in this photo...</td>', 'This is a great shot.  I really feel the action in this photo...', '2003-09-19 17:31:39.000000', NULL, 1),
(424260, 37808, 10620, '<td valign="top">ginger says sweet moves girl...nice vw</td>', 'ginger says sweet moves girl...nice vw', '2003-09-19 19:15:42.000000', NULL, 1),
(424286, 37596, 5351, '<td valign="top">This is a fun shot- I''m always amazed at what dogs can do!  Excellent background - really lets the focus remain on the subject, yet complements it.  Also think you made an excellent border selection.  Very good shot - good luck!</td>', 'This is a fun shot- I''m always amazed at what dogs can do!  Excellent background - really lets the focus remain on the subject, yet complements it.  Also think you made an excellent border selection.  Very good shot - good luck!', '2003-09-19 21:27:00.000000', NULL, 1),
(424287, 37508, 5351, '<td valign="top">Nice capture - great colors and I really like the angle this was taken from.  Would like to know what track this was taken at.  The focus is very good:)</td>', 'Nice capture - great colors and I really like the angle this was taken from.  Would like to know what track this was taken at.  The focus is very good:)', '2003-09-19 21:29:37.000000', NULL, 1),
(424289, 37551, 9241, '<td valign="top">maybe a little over sharpened,I think cropping out the fans on top would have focused my attention more, Nice movement on the bat, did he hit it?</td>', 'maybe a little over sharpened,I think cropping out the fans on top would have focused my attention more, Nice movement on the bat, did he hit it?', '2003-09-19 21:33:18.000000', NULL, 1),
(424290, 37787, 5351, '<td valign="top">Really like the composition on this.  Excellent focus and the DOF in my opinion is excellent.  good job:)</td>', 'Really like the composition on this.  Excellent focus and the DOF in my opinion is excellent.  good job:)', '2003-09-19 21:33:55.000000', NULL, 1),
(424291, 37613, 9241, '<td valign="top">I''d love to see it with the focus on the defender. Nice capture</td>', 'I''d love to see it with the focus on the defender. Nice capture', '2003-09-19 21:34:51.000000', NULL, 1),
(424294, 37551, 10084, '<td valign="top">Great composition. Really shows where the action is. Good capture of the swinging bat.  I like that you were able to include the audience, the teammates, and the next batter. Makes you feel like you''re at the game.</td>', 'Great composition. Really shows where the action is. Good capture of the swinging bat.  I like that you were able to include the audience, the teammates, and the next batter. Makes you feel like you''re at the game.', '2003-09-19 21:36:48.000000', NULL, 1),
(424295, 37715, 5351, '<td valign="top">I like the idea of this.  I would like to see this cropped higher up, eliminating two thirds of the grass - abouth where the darker grass starts.  I like the photo but my eye is drawn more to the contrasts in the grass color than the net.  perhaps I am the only one who feels that way though:)</td>', 'I like the idea of this.  I would like to see this cropped higher up, eliminating two thirds of the grass - abouth where the darker grass starts.  I like the photo but my eye is drawn more to the contrasts in the grass color than the net.  perhaps I am the only one who feels that way though:)', '2003-09-19 21:38:23.000000', NULL, 1),
(424298, 37615, 10084, '<td valign="top">Good scrimmage shot. The bright colors of the uniforms really bring out the players from the background. It really brings the players forwar. A bit of blurring brings out the action. I like the low on the field shot. Makes you feel like you''re there in person.</td>', 'Good scrimmage shot. The bright colors of the uniforms really bring out the players from the background. It really brings the players forwar. A bit of blurring brings out the action. I like the low on the field shot. Makes you feel like you''re there in person.', '2003-09-19 21:39:08.000000', NULL, 1),
(424300, 37745, 9241, '<td valign="top">He either wipes or didnt play that day!Way too clean, no points deducted;)Would really love it with a big red/orange splotch somewhere</td>', 'He either wipes or didnt play that day!Way too clean, no points deducted;)Would really love it with a big red/orange splotch somewhere', '2003-09-19 21:39:46.000000', NULL, 1),
(424301, 37840, 9241, '<td valign="top">sorry cute thought but ...sport?</td>', 'sorry cute thought but ...sport?', '2003-09-19 21:41:28.000000', NULL, 1),
(424302, 37824, 5351, '<td valign="top">Wow!  This is great - one of my favorites in the challenge so far!  The DOF is excellent.  This photo makes you want to know what happened next.  I also love the lighting on the club.  Great job - hope you do well in the challenge:)</td>', 'Wow!  This is great - one of my favorites in the challenge so far!  The DOF is excellent.  This photo makes you want to know what happened next.  I also love the lighting on the club.  Great job - hope you do well in the challenge:)', '2003-09-19 21:42:19.000000', NULL, 1),
(424303, 37790, 9241, '<td valign="top">subject out of focus, way too much water</td>', 'subject out of focus, way too much water', '2003-09-19 21:43:24.000000', NULL, 1),
(424304, 37615, 5351, '<td valign="top">Nice colors!</td>', 'Nice colors!', '2003-09-19 21:45:58.000000', NULL, 1),
(424305, 37200, 9241, '<td valign="top">border/frame is too big. the speed shows but I''d like to see some focus</td>', 'border/frame is too big. the speed shows but I''d like to see some focus', '2003-09-19 21:46:00.000000', NULL, 1),
(424306, 37134, 5351, '<td valign="top">Great shot!  the background has a surreal feel to it - almost dreamlike which I think complements the subject very well.  Good job:)</td>', 'Great shot!  the background has a surreal feel to it - almost dreamlike which I think complements the subject very well.  Good job:)', '2003-09-19 21:50:27.000000', NULL, 1),
(424307, 37807, 9241, '<td valign="top">next frame..faceplant. Great shot</td>', 'next frame..faceplant. Great shot', '2003-09-19 21:51:39.000000', NULL, 1),
(424309, 37652, 5351, '<td valign="top">Cool shot!</td>', 'Cool shot!', '2003-09-19 21:52:34.000000', NULL, 1),
(424310, 37655, 9241, '<td valign="top">Kinda dark, I think maybe you exposed for the sky. Location is a little distracting with the parking lot/tennis courts</td>', 'Kinda dark, I think maybe you exposed for the sky. Location is a little distracting with the parking lot/tennis courts', '2003-09-19 21:53:33.000000', NULL, 1),
(424311, 37842, 9241, '<td valign="top">blatant sponser plug, but WOW</td>', 'blatant sponser plug, but WOW', '2003-09-19 21:55:04.000000', NULL, 1),
(424314, 37807, 5351, '<td valign="top">What a great shot - absolutely love the collors and the focus could not be better.  I can''t think of a single thing I could suggest to improve this - good luck in the challenge!</td>', 'What a great shot - absolutely love the collors and the focus could not be better.  I can''t think of a single thing I could suggest to improve this - good luck in the challenge!', '2003-09-19 21:58:38.000000', NULL, 1),
(424316, 37852, 5351, '<td valign="top">What a great eye you have - I love it when people see more than the obvious.  border is very good as well.  Also really like the effect of the lighting on the top part of the hoop.  Good job.</td>', 'What a great eye you have - I love it when people see more than the obvious.  border is very good as well.  Also really like the effect of the lighting on the top part of the hoop.  Good job.', '2003-09-19 22:00:43.000000', NULL, 1),
(424318, 37635, 5351, '<td valign="top">This is a great shot - could not meet the challenge any better.  So much action going on and its all in great focus.  Looks like a shot from Sports Illustrated!  High score:)</td>', 'This is a great shot - could not meet the challenge any better.  So much action going on and its all in great focus.  Looks like a shot from Sports Illustrated!  High score:)', '2003-09-19 22:04:46.000000', NULL, 1),
