(424328, 37568, 9241, '<td valign="top">the balls are great the cue could have been cropped out it is distracting<br/></td>', 'the balls are great the cue could have been cropped out it is distracting', '2003-09-19 22:14:52.000000', NULL, 1),
(424329, 37417, 9241, '<td valign="top">why duotone? Nodeduction just curious.</td>', 'why duotone? Nodeduction just curious.', '2003-09-19 22:15:45.000000', NULL, 1),
(424340, 37595, 9241, '<td valign="top">Beautiful colors but the subject is way to dark....what is it?</td>', 'Beautiful colors but the subject is way to dark....what is it?', '2003-09-19 22:21:26.000000', NULL, 1),
