(425140, 37508, 2125, '<td valign="top">i can almost hear the thunder!!  nice colors!! 8</td>', 'i can almost hear the thunder!!  nice colors!! 8', '2003-09-21 19:11:35.000000', NULL, 1),
(425141, 37736, 2125, '<td valign="top">nice shot did you try using the ''cloudy'' white balance setting? might have brightened it up a bit!<br/></td>', 'nice shot did you try using the ''cloudy'' white balance setting? might have brightened it up a bit!', '2003-09-21 19:12:16.000000', NULL, 1),
