(425144, 37594, 2125, '<td valign="top">nice use of framing here and good sepia tone!!</td>', 'nice use of framing here and good sepia tone!!', '2003-09-21 19:13:07.000000', NULL, 1),
(425145, 37842, 10608, '<td valign="top">This photo is very original and I love it. I like the luminacity of the light. Good job!</td>', 'This photo is very original and I love it. I like the luminacity of the light. Good job!', '2003-09-21 19:13:31.000000', NULL, 1),
