(425148, 37808, 2125, '<td valign="top">cute nice dof to get the van in focus!</td>', 'cute nice dof to get the van in focus!', '2003-09-21 19:14:34.000000', NULL, 1),
(425149, 37835, 10608, '<td valign="top">Very nice composition and lively color.</td>', 'Very nice composition and lively color.', '2003-09-21 19:14:37.000000', NULL, 1),
