(425157, 37524, 2125, '<td valign="top">perfect capture would like to see the spot edited version with the wall the same color and no black spot 9 none the less!</td>', 'perfect capture would like to see the spot edited version with the wall the same color and no black spot 9 none the less!', '2003-09-21 19:18:32.000000', NULL, 1),
