(425160, 37563, 2125, '<td valign="top">great light focus and composition Nike is going to love us! 9</td>', 'great light focus and composition Nike is going to love us! 9', '2003-09-21 19:20:37.000000', NULL, 1),
(425161, 37426, 2125, '<td valign="top">i like the cocept seems a bit dull on colors and ball is hot but not sure what you could do differently nice rule of thirds focus is okay</td>', 'i like the cocept seems a bit dull on colors and ball is hot but not sure what you could do differently nice rule of thirds focus is okay', '2003-09-21 19:21:42.000000', NULL, 1),
(425178, 37648, 5705, '<td valign="top">pretty sharp and nice DOF-- 8</td>', 'pretty sharp and nice DOF-- 8', '2003-09-21 20:17:35.000000', NULL, 1),
(425179, 37643, 5705, '<td valign="top">Good Action</td>', 'Good Action', '2003-09-21 20:17:52.000000', NULL, 1),
(425180, 37042, 5705, '<td valign="top">Very cool shot, and original aslo!! -9</td>', 'Very cool shot, and original aslo!! -9', '2003-09-21 20:19:09.000000', NULL, 1),
(425181, 37835, 5705, '<td valign="top">THis so far is the cleanest and best emotion I have seen in the challenge-- 10++</td>', 'THis so far is the cleanest and best emotion I have seen in the challenge-- 10++', '2003-09-21 20:19:59.000000', NULL, 1),
(425182, 37802, 5705, '<td valign="top">Very Professional--  A cover shot-- 10</td>', 'Very Professional--  A cover shot-- 10', '2003-09-21 20:20:34.000000', NULL, 1),
