(425308, 37648, 11073, '<td valign="top">good dof.</td>', 'good dof.', '2003-09-21 23:19:12.000000', NULL, 1),
(425310, 37643, 8159, '<td valign="top">Great capture. Lots of action going on -- you can really feel the "energy" of the play in this shot. There is some subtle blurring going on which works here -- but the ball carrier''s face is crisp which is very cool.</td>', 'Great capture. Lots of action going on -- you can really feel the "energy" of the play in this shot. There is some subtle blurring going on which works here -- but the ball carrier''s face is crisp which is very cool.', '2003-09-21 23:22:56.000000', NULL, 1),
